{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children_map = {}
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            children_map.setdefault(p, []).append(n['id'])
    removed = set()
    removal_order = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if nid in removed:
            continue
        if not n.get('removable', False):
            continue
        if n['symbol'] in required_symbols:
            continue
        retained_children = any(c not in removed for c in children_map.get(nid, []))
        if retained_children:
            continue
        removed.add(nid)
        removal_order.append(nid)
    retained = sorted([nd['id'] for nd in nodes if nd['id'] not in removed])
    return {'removed_node_ids': removal_order, 'retained_node_ids': retained}"
}
